            my $op_info = $self->lookup_operator($candidate);
            if ($op_info) {
                $operator = $candidate;
                $prec_level = $op_info->{level};
            }
        }
    }

    return Chalk::Semiring::PrecedenceElement->new(
        valid => 1,
        operator => $operator,
        precedence_level => $prec_level
